const key = `order-${orderId}`;   // 클라이언트가 만들고 재시도 시 동일하게
await fetch('/pay', {
  method: 'POST',
  headers: { 'Idempotency-Key': key },   // 재시도해도 같은 key
  body: JSON.stringify({ orderId, amount }),
});
// 서버: 이 key 를 이미 처리했으면 저장된 응답을 그대로 반환(결제 안 함)

const seen = await db.markWebhookSeen(event.id);   // 이미 있으면 false
if (!seen) return res.status(200).end();           // 이미 처리 → 조용히 200
// 처음 보는 이벤트만 처리 (재고·포인트·이메일 등 부작용)
await applyPaymentEffects(event);
return res.status(200).end();                      // 빨리 200 을 줘야 재전송 안 됨
